ClipboardPage classKeyPage = tools.findPage("ClassKeyPage");

//Get the key information
String keyName = myStepPage.getProperty("pyKeyName").getStringValue();
String keyLabel = myStepPage.getProperty("pyKeyCaption").getStringValue();
String keyValue = tools.getPrimaryPage().getProperty(keyName).getStringValue().trim();

// Set this key property on ClassKeyPage
classKeyPage.getProperty(keyName).setValue(keyValue);

// Call ValidateKeysContent
ParameterPage newParamsPage = new ParameterPage();
newParamsPage.putString("strKeyName", keyName);
newParamsPage.putString("strKeyLabel", keyLabel);
newParamsPage.putString("strKeyValue", keyValue);
newParamsPage.putString("continue", "true");
HashStringMap params = new HashStringMap();
params.putString("pxObjClass", "Rule-Obj-Activity");
params.putString("pyClassName", tools.getPrimaryPage().getClassName());
params.putString("pyActivityName", "ValidateKeysContent");
tools.doActivity(params, tools.getPrimaryPage(), newParamsPage);

// some applications may only want ValidateKeysContent called once
if (newParamsPage.getString("continue").equalsIgnoreCase("false"))
   nextBlock = "T";

// maybe the errors were simply because there were spaces in the keys
// and if we just strip those spaces, we'll be fine
ClipboardProperty keyInfo = tools.findPage("ClassToValidate").getProperty(".pyKeyDefList");
java.util.Iterator keyIt = keyInfo.iterator();
while (keyIt.hasNext())
{
   ClipboardProperty keyRef = (ClipboardProperty)keyIt.next();
   String strKeyName = keyRef.getPageValue().getString(".pyKeyName");

   ClipboardProperty cpKey = myStepPage.getProperty(strKeyName);
   String strKeyVal = cpKey.getStringValue();

   // remove the spaces from the key
   strKeyVal = pega_rules_string.replaceAll(strKeyVal, " ", "");
   cpKey.setValue(strKeyVal);
   tools.getPrimaryPage().getProperty(strKeyName).setValue(strKeyVal);
}

bRemovedSpacesFromKeys = true;

tools.getPrimaryPage().clearMessages();
// copy the error messages from the step page to the primary page
String strErrorMessages = myStepPage.getMessagesAll();
if (strErrorMessages.length() > 0)
   tools.getPrimaryPage().addMessage(strErrorMessages);
else if (bRemovedSpacesFromKeys)
   tools.putParamValue("removeSpaces", true);
